import { test, expect } from '@playwright/test';

test.describe('Promo Code Application and Discounted Total', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/cart');
  });

  test('should successfully apply a valid promo code and display discounted total', async ({ page }) => {
    // Verify initial cart total is visible
    const initialTotal = page.getByRole('heading', { name: /cart total/i }).first();
    await expect(initialTotal).toBeVisible();

    // Verify initial total value
    const initialTotalValue = page.getByText(/\$\d+\.\d{2}/).first();
    await expect(initialTotalValue).toBeVisible();

    // Locate and fill promo code input using getByLabel
    const promoCodeInput = page.getByLabel('Promo Code');
    await expect(promoCodeInput).toBeVisible();
    await promoCodeInput.fill('SUMMER20');

    // Locate and click apply button using getByRole
    const applyButton = page.getByRole('button', { name: /apply promo code/i });
    await expect(applyButton).toBeVisible();
    await applyButton.click();

    // Wait for API response and discount to be applied
    await page.waitForResponse(response => 
      response.url().includes('/api/promo-code') && response.status() === 200
    );

    // Verify success message appears
    const successMessage = page.getByText(/promo code applied successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify discount percentage is displayed
    const discountText = page.getByText(/20% discount applied/i);
    await expect(discountText).toBeVisible();

    // Verify discounted total is displayed and is less than initial total
    const discountedTotalValue = page.getByText(/\$\d+\.\d{2}/).last();
    await expect(discountedTotalValue).toBeVisible();

    const initialTotalText = page.getByText(/\$\d+\.\d{2}/).first();
    const initialTotalAmount = parseFloat(initialTotalText.textContent?.replace('$', '').replace(',', ''));
    const discountedTotalAmount = parseFloat(discountedTotalValue.textContent?.replace('$', '').replace(',', ''));

    expect(discountedTotalAmount).toBeLessThan(initialTotalAmount);
    expect(discountedTotalAmount).toBeCloseTo(initialTotalAmount * 0.8, 2);
  });

  test('should display error message when applying an invalid promo code', async ({ page }) => {
    // Locate and fill promo code input using getByLabel
    const promoCodeInput = page.getByLabel('Promo Code');
    await expect(promoCodeInput).toBeVisible();
    await promoCodeInput.fill('INVALIDCODE123');

    // Locate and click apply button using getByRole
    const applyButton = page.getByRole('button', { name: /apply promo code/i });
    await expect(applyButton).toBeVisible();
    await applyButton.click();

    // Wait for API response
    await page.waitForResponse(response => 
      response.url().includes('/api/promo-code') && response.status() === 400
    );

    // Verify error message appears
    const errorMessage = page.getByText(/invalid promo code/i);
    await expect(errorMessage).toBeVisible();

    // Verify discount message does not appear
    const discountText = page.getByText(/promo code applied successfully/i);
    await expect(discountText).not.toBeVisible();

    // Verify total price remains unchanged
    const initialTotalValue = page.getByText(/\$\d+\.\d{2}/).first();
    await expect(initialTotalValue).toBeVisible();

    const totalAmount = parseFloat(initialTotalValue.textContent?.replace('$', '').replace(',', ''));
    expect(totalAmount).toBeGreaterThan(0);
  });
});
